window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-02fdc1c50ae43c91"]={"versions": [{"id": "FIG-02fdc1c50ae43c91", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd Nv M_GetVersionInfo</code>) zur Darstellung des synchronen Ablaufs der Versionsabfrage im AUTOSAR NVRAM Manager (NvM). Das Diagramm beschreibt den Aufruf der API <code>NvM_GetVersionInfo</code> aus der Anwendungsperspektive (Interaction Views).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten sind:</p>\n<ul class=\"fig-list\"><li><code>SW Component</code> (mit Kontextvermerk <code>(from Interaction Views)</code>): Aufrufende Software-Komponente.\n</li><li><code>Nv M ::Nv M</code>: Ziel-Lebenslinie des NVRAM-Managers mit Dekompositionssymbol.\n</li><li>Schnittstellenoperation: Synchroner Aufruf <code>NvM_GetVersionInfo(versioninfo)</code> mit Rücksprung <code>NvM_GetVersionInfo</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>SW Component</code> ruft synchron über eine durchgezogene Pfeillinie mit gefüllter Pfeilspitze <code>NvM_GetVersionInfo(versioninfo)</code> an <code>Nv M ::Nv M</code> auf.\n</li><li>Während des Aufrufs ist auf beiden Lebenslinien ein Aktivierungsbalken aktiv.\n</li><li><code>Nv M ::Nv M</code> antwortet synchron über eine gestrichelte Pfeillinie mit offener Pfeilspitze (<code>NvM_GetVersionInfo</code>) an <code>SW Component</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Sequenz spezifiziert die standardisierte synchrone Abfrage der Modulinformationen. Der Parameter <code>versioninfo</code> dient zur Aufnahme der Versionsdaten des NvM-Moduls. Da der Aufruf synchron blockierend ist, erfolgt die Rückmeldung unmittelbar nach Ermittlung der Daten.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-033e7a8f1a3aaf85", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd Nv M_GetVersionInfo</code>) zur Darstellung des synchronen Ablaufs der Versionsabfrage im AUTOSAR NVRAM Manager (NvM). Das Diagramm beschreibt den Aufruf der API <code>NvM_GetVersionInfo</code> aus der Anwendungsperspektive (Interaction Views).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten sind:</p>\n<ul class=\"fig-list\"><li><code>Generic Elements::NvM User</code>: Aufrufende Nutzerentität des NvM.\n</li><li><code>«module» NvM::NvM</code>: Stereotypisiertes Modul des NVRAM-Managers mit Dekompositionssymbol.\n</li><li>Kommentarblock: Spezifikationsvermerk <code>Status: Proposed by TO as per NvM SWS 1.44</code> mit leeren Feldern <code>Description:</code> und <code>Comments:</code>.\n</li><li>Schnittstellenoperation: Synchroner Aufruf <code>NvM_GetVersionInfo(versioninfo)</code> mit Rücksprung <code>NvM_GetVersionInfo</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>SW Component</code> ruft synchron über eine durchgezogene Pfeillinie mit gefüllter Pfeilspitze <code>NvM_GetVersionInfo(versioninfo)</code> an <code>Nv M ::Nv M</code> auf.\n</li><li>Während des Aufrufs ist auf beiden Lebenslinien ein Aktivierungsbalken aktiv.\n</li><li><code>Nv M ::Nv M</code> antwortet synchron über eine gestrichelte Pfeillinie mit offener Pfeilspitze (<code>NvM_GetVersionInfo</code>) an <code>SW Component</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Sequenz spezifiziert die standardisierte synchrone Abfrage der Modulinformationen. Der Parameter <code>versioninfo</code> dient zur Aufnahme der Versionsdaten des NvM-Moduls. Da der Aufruf synchron blockierend ist, erfolgt die Rückmeldung unmittelbar nach Ermittlung der Daten.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-e8f9ccb7ba928b5b", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm ohne äußeren Interaktionsrahmen, das den synchronen Funktionsaufruf zur Ermittlung der Versionsinformationen des NVRAM-Managers im AUTOSAR-Basissoftware-Kontext darstellt.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten sind:</p>\n<ul class=\"fig-list\"><li><code>NvM User</code>: Generischer Aufrufer der Basissoftware bzw. Anwendungsschicht.\n</li><li><code>«module» NvM</code>: NVRAM-Manager-Basissoftwaremodul mit Dekompositionssymbol.\n</li><li>Schnittstellenoperation: Synchroner Aufruf <code>NvM_GetVersionInfo(Std_VersionInfoType**)</code> und zugehörige Rückkehrantwort <code>NvM_GetVersionInfo()</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>NvM User</code> ruft über einen synchronen Operationsaufruf (durchgezogene Linie, gefüllte Pfeilspitze) <code>NvM_GetVersionInfo(Std_VersionInfoType**)</code> am Modul <code>NvM</code> auf.\n</li><li>Auf beiden Lebenslinien signalisiert ein Ausführungsfokus die Bearbeitung.\n</li><li><code>NvM</code> kehrt über eine gestrichelte Linie mit offener Pfeilspitze (<code>NvM_GetVersionInfo()</code>) zum Aufrufer zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Aufruf erfordert die Übergabe eines Zeigers auf die Versionsinformationsstruktur (<code>Std_VersionInfoType**</code>). Die Funktion arbeitet synchron und gibt die Major-, Minor- und Patch-Versionsnummern sowie Vendor-IDs des NvM zurück.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-f36083c35d5ad7e2", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm ohne äußeren Interaktionsrahmen, das den synchronen Funktionsaufruf zur Ermittlung der Versionsinformationen des NVRAM-Managers im AUTOSAR-Basissoftware-Kontext darstellt.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten sind:</p>\n<ul class=\"fig-list\"><li><code>NvM User</code>: Aufrufer der Basissoftware bzw. Anwendungsschicht.\n</li><li><code>«module» NvM</code>: NVRAM-Manager-Basissoftwaremodul mit Dekompositionssymbol.\n</li><li>Schnittstellenoperation: Synchroner Aufruf <code>NvM_GetVersionInfo(Std_VersionInfoType*)</code> und zugehörige Rückkehrantwort <code>NvM_GetVersionInfo()</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>NvM User</code> ruft über einen synchronen Operationsaufruf (durchgezogene Linie, gefüllte Pfeilspitze) <code>NvM_GetVersionInfo(Std_VersionInfoType*)</code> am Modul <code>NvM</code> auf.\n</li><li>Auf beiden Lebenslinien signalisiert ein Ausführungsfokus die synchrone Bearbeitung.\n</li><li><code>NvM</code> kehrt über eine gestrichelte Linie mit offener Pfeilspitze (<code>NvM_GetVersionInfo()</code>) zum Aufrufer zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der synchrone Aufruf erwartet gemäß AUTOSAR-Standard einen einfachen Zeiger auf eine vom Aufrufer bereitgestellte Struktur vom Typ <code>Std_VersionInfoType</code> (<code>Std_VersionInfoType*</code>), in welche die Modulinformationen geschrieben werden.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-07e356340978ee39", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm ohne äußeren Interaktionsrahmen, das den synchronen Funktionsaufruf zur Ermittlung der Versionsinformationen des NVRAM-Managers im AUTOSAR-Basissoftware-Kontext darstellt.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten sind:</p>\n<ul class=\"fig-list\"><li><code>NvM User</code>: Aufrufer der Basissoftware bzw. Anwendungsschicht.\n</li><li><code>«module» NvM</code>: NVRAM-Manager-Basissoftwaremodul mit Dekompositionssymbol.\n</li><li>Schnittstellenoperation: Synchroner Aufruf <code>NvM_GetVersionInfo(Std_VersionInfoType*)</code> und zugehörige Rückkehrantwort <code>NvM_GetVersionInfo()</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>NvM User</code> ruft über einen synchronen Operationsaufruf (durchgezogene Linie, gefüllte Pfeilspitze) <code>NvM_GetVersionInfo(Std_VersionInfoType*)</code> am Modul <code>NvM</code> auf.\n</li><li>Auf beiden Lebenslinien signalisiert ein Ausführungsfokus die synchrone Bearbeitung.\n</li><li><code>NvM</code> kehrt über eine gestrichelte Linie mit offener Pfeilspitze (<code>NvM_GetVersionInfo()</code>) zum Aufrufer zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der synchrone Aufruf erwartet gemäß AUTOSAR-Standard einen einfachen Zeiger auf eine vom Aufrufer bereitgestellte Struktur vom Typ <code>Std_VersionInfoType</code> (<code>Std_VersionInfoType*</code>), in welche die Modulinformationen geschrieben werden.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-5065911b96cf7326", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm ohne äußeren Interaktionsrahmen, das den synchronen Funktionsaufruf zur Ermittlung der Versionsinformationen des NVRAM-Managers im AUTOSAR-Basissoftware-Kontext darstellt.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten sind:</p>\n<ul class=\"fig-list\"><li><code>NvM User</code>: Aufrufer der Basissoftware bzw. Anwendungsschicht.\n</li><li><code>«module» NvM</code>: NVRAM-Manager-Basissoftwaremodul mit Dekompositionssymbol.\n</li><li>Schnittstellenoperation: Synchroner Aufruf <code>NvM_GetVersionInfo(Std_VersionInfoType**)</code> und zugehörige Rückkehrantwort <code>NvM_GetVersionInfo()</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>NvM User</code> ruft über einen synchronen Aufruf <code>NvM_GetVersionInfo</code> mit dem Parameter <code>(Std_VersionInfoType**)</code> am Modul <code>NvM</code> auf.\n</li><li>Beide Lebenslinien zeigen den Ausführungsbalken während der Abarbeitung.\n</li><li><code>NvM</code> liefert über eine gestrichelte Rückkehrlinie <code>NvM_GetVersionInfo()</code> die Kontrolle an <code>NvM User</code> zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Diagrammbeschriftung spezifiziert die Übergabe eines Zeigers auf einen Zeiger (<code>Std_VersionInfoType**</code>) für die Abfrage der Modulinformationen. Der Aufruf erfolgt synchron und blockierend.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-f94eca469d8725b2", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm ohne äußeren Interaktionsrahmen, das den synchronen Funktionsaufruf zur Ermittlung der Versionsinformationen des NVRAM-Managers im AUTOSAR-Basissoftware-Kontext darstellt.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten sind:</p>\n<ul class=\"fig-list\"><li><code>NvM User</code>: Aufrufer der Basissoftware bzw. Anwendungsschicht.\n</li><li><code>«module» NvM</code>: NVRAM-Manager-Basissoftwaremodul mit Dekompositionssymbol.\n</li><li>Schnittstellenoperation: Synchroner Aufruf <code>NvM_GetVersionInfo(Std_VersionInfoType**)</code> und zugehörige Rückkehrantwort <code>NvM_GetVersionInfo()</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>NvM User</code> ruft über einen synchronen Aufruf <code>NvM_GetVersionInfo</code> mit dem Parameter <code>(Std_VersionInfoType**)</code> am Modul <code>NvM</code> auf.\n</li><li>Beide Lebenslinien zeigen den Ausführungsbalken während der Abarbeitung.\n</li><li><code>NvM</code> liefert über eine gestrichelte Rückkehrlinie <code>NvM_GetVersionInfo()</code> die Kontrolle an <code>NvM User</code> zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Diagrammbeschriftung spezifiziert die Übergabe eines Zeigers auf einen Zeiger (<code>Std_VersionInfoType**</code>) für die Abfrage der Modulinformationen. Der Aufruf erfolgt synchron und blockierend.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-a1eda57ae55e0c54", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm ohne äußeren Interaktionsrahmen, das den synchronen Funktionsaufruf zur Ermittlung der Versionsinformationen des NVRAM-Managers im AUTOSAR-Basissoftware-Kontext darstellt.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten sind:</p>\n<ul class=\"fig-list\"><li><code>NvM User</code>: Aufrufer der Basissoftware bzw. Anwendungsschicht.\n</li><li><code>«module» NvM</code>: NVRAM-Manager-Basissoftwaremodul mit Dekompositionssymbol.\n</li><li>Schnittstellenoperation: Synchroner Aufruf <code>NvM_GetVersionInfo(Std_VersionInfoType**)</code> und zugehörige Rückkehrantwort <code>NvM_GetVersionInfo()</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>NvM User</code> ruft über einen synchronen Aufruf <code>NvM_GetVersionInfo</code> mit dem Parameter <code>(Std_VersionInfoType**)</code> am Modul <code>NvM</code> auf.\n</li><li>Beide Lebenslinien zeigen den Ausführungsbalken während der Abarbeitung.\n</li><li><code>NvM</code> liefert über eine gestrichelte Rückkehrlinie <code>NvM_GetVersionInfo()</code> die Kontrolle an <code>NvM User</code> zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Diagrammbeschriftung spezifiziert die Übergabe eines Zeigers auf einen Zeiger (<code>Std_VersionInfoType**</code>) für die Abfrage der Modulinformationen. Der Aufruf erfolgt synchron und blockierend.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-b2c7853974aaf324", "releases": ["R22-11", "R23-11", "R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm ohne äußeren Interaktionsrahmen, das den synchronen Funktionsaufruf zur Ermittlung der Versionsinformationen des NVRAM-Managers im AUTOSAR-Basissoftware-Kontext darstellt.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten sind:</p>\n<ul class=\"fig-list\"><li><code>NvM User</code>: Aufrufer der Basissoftware bzw. Anwendungsschicht.\n</li><li><code>«module» NvM</code>: NVRAM-Manager-Basissoftwaremodul mit Dekompositionssymbol.\n</li><li>Schnittstellenoperation: Synchroner Aufruf <code>NvM_GetVersionInfo(Std_VersionInfoType**)</code> und zugehörige Rückkehrantwort <code>NvM_GetVersionInfo()</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>NvM User</code> ruft über einen synchronen Aufruf <code>NvM_GetVersionInfo</code> mit dem Parameter <code>(Std_VersionInfoType**)</code> am Modul <code>NvM</code> auf.\n</li><li>Beide Lebenslinien zeigen den Ausführungsbalken während der Abarbeitung.\n</li><li><code>NvM</code> liefert über eine gestrichelte Rückkehrlinie <code>NvM_GetVersionInfo()</code> die Kontrolle an <code>NvM User</code> zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Diagrammbeschriftung spezifiziert die Übergabe eines Zeigers auf einen Zeiger (<code>Std_VersionInfoType**</code>) für die Abfrage der Modulinformationen. Der Aufruf erfolgt synchron und blockierend.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-02fdc1c50ae43c91", "to": "FIG-033e7a8f1a3aaf85", "fr": "R2.1.20", "tr": "R3.0.7", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><strong>Interaktionsrahmen</strong>: Der Kontext-Zusatz <code>(from Interaction Views)</code> unter dem Aufrufer-Kopf entfällt; ein Dokumentationskommentarblock (<code>Status: Proposed by TO as per NvM SWS 1.44</code>, <code>Description:</code>, <code>Comments:</code>) wurde links unten hinzugefügt.\n</li><li><strong>Lebenslinie Aufrufer</strong>: Umbenannt von <code>SW Component</code> zu <code>Generic Elements::NvM User</code>.\n</li><li><strong>Lebenslinie NvM</strong>: Stereotyp <code>«module»</code> ergänzt, Paketpräfix im Kopftext von <code>Nv M ::Nv M</code> zu <code>NvM::NvM</code> vereinheitlicht.\n</li></ul>"}, {"from": "FIG-033e7a8f1a3aaf85", "to": "FIG-e8f9ccb7ba928b5b", "fr": "R3.1.5", "tr": "R4.0.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong>Interaktionsrahmen</strong>: Der äußere UML-Rahmen <code>sd Nv M_GetVersionInfo</code> sowie der Dokumentationskommentarblock entfallen vollständig.\n</li><li><strong>Lebenslinien</strong>: Aufrufer umbenannt von <code>Generic Elements::NvM User</code> zu <code>NvM User</code>; Zielmodul umbenannt von <code>NvM::NvM</code> zu <code>NvM</code>.\n</li><li><strong>Aufruf-Nachricht</strong>: Parameter typisiert von generischem <code>versioninfo</code> zu <code>Std_VersionInfoType**</code> (<code>NvM_GetVersionInfo(Std_VersionInfoType**)</code>).\n</li><li><strong>Rückkehr-Nachricht</strong>: Von <code>NvM_GetVersionInfo</code> präzisiert zu <code>NvM_GetVersionInfo()</code>.\n</li></ul>"}, {"from": "FIG-e8f9ccb7ba928b5b", "to": "FIG-f36083c35d5ad7e2", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong>Aufruf-Nachricht</strong>: Parameter-Indirektionsgrad korrigiert von Doppelzeiger <code>Std_VersionInfoType**</code> zu Einzelzeiger <code>Std_VersionInfoType*</code> (<code>NvM_GetVersionInfo(Std_VersionInfoType*)</code>).\n</li></ul>"}, {"from": "FIG-f36083c35d5ad7e2", "to": "FIG-07e356340978ee39", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-07e356340978ee39", "to": "FIG-5065911b96cf7326", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong>Aufruf-Nachricht</strong>: Parameter-Indirektionsgrad geändert von Einzelzeiger <code>Std_VersionInfoType*</code> zurück zu Doppelzeiger <code>Std_VersionInfoType**</code> (dargestellt mit Zeilenumbruch: <code>NvM_GetVersionInfo\\n(Std_VersionInfoType**)</code>).\n</li><li><strong>Rückkehr-Nachricht</strong>: Darstellung des Methodenbezeichners zweizeilig aufgeteilt mit umgebrochener Klammer <code>()</code>.\n</li></ul>"}, {"from": "FIG-5065911b96cf7326", "to": "FIG-f94eca469d8725b2", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-f94eca469d8725b2", "to": "FIG-a1eda57ae55e0c54", "fr": "R20-11", "tr": "R21-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Gesamtdiagramm: Neu gerendert mit leicht veränderten Schriftabständen und Linienstärken ohne Änderung der Modellelemente, Schnittstellen oder Bezeichner.\n</li></ul>"}, {"from": "FIG-a1eda57ae55e0c54", "to": "FIG-b2c7853974aaf324", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
